@Override
    public void render(DancingBladeVisualEntity entity, float yaw, float tickDelta, MatrixStack matrices, VertexConsumerProvider vertexConsumers, int light) {
        ItemStack stack = entity.getWeaponStack();
        if (stack == null || stack.isEmpty()) {
            return;
        }

        int maxSwords = Math.max(1, net.sweenus.simplyswords.config.Config.gemPowers.dancingBlades.maxSwords);
        Vec3d center = getRenderCenter(entity, tickDelta);
        Vec3d entityPos = new Vec3d(
                MathHelper.lerp(tickDelta, entity.prevX, entity.getX()),
                MathHelper.lerp(tickDelta, entity.prevY, entity.getY()),
                MathHelper.lerp(tickDelta, entity.prevZ, entity.getZ())
        );
        double baseAngle = getSmoothRenderPhase(entity, tickDelta);
        double angle = baseAngle + ((Math.PI * 2.0) / maxSwords) * entity.getOrbitSlot();
        double bob = Math.sin(baseAngle * (BOB_SPEED / BASE_ANGULAR_SPEED) + entity.getOrbitSlot() * 1.7) * BOB_AMPLITUDE;
        Vec3d bladePos = center.add(Math.cos(angle) * Math.max(0.5F, entity.getOrbitRadius()), BLADE_HEIGHT + bob, Math.sin(angle) * Math.max(0.5F, entity.getOrbitRadius()));
        Vec3d offset = bladePos.subtract(entityPos);

        float renderAge = entity.age + tickDelta;
        float attackProgress = getAttackProgress(entity, tickDelta);
        AttackPose attackPose = getAttackPose(attackProgress);
        float spin = (float) Math.toDegrees(-angle) + 90.0F;
        float idleTilt = 35.0F + MathHelper.sin(renderAge * 0.12F + entity.getOrbitSlot()) * 7.0F;

        matrices.push();
        matrices.translate(offset.x, offset.y, offset.z);
        matrices.multiply(RotationAxis.POSITIVE_Y.rotationDegrees(spin));
        matrices.multiply(RotationAxis.POSITIVE_Z.rotationDegrees(idleTilt + attackPose.impactRoll));
        BakedModel model = this.itemRenderer.getModels().getModel(stack);
        this.itemRenderer.renderItem(
                stack,
                ModelTransformationMode.GROUND,
                false,
                matrices,
                vertexConsumers,
                light,
                OverlayTexture.DEFAULT_UV,
                model
        );
        matrices.pop();
        super.render(entity, yaw, tickDelta, matrices, vertexConsumers, light);
    }

private static void drawSweepingCrescent(VertexConsumer vertices, Matrix4f matrix,
                                              float progress, float radiusX, float radiusY,
                                              float thickness, int red, int green, int blue,
                                              int alpha, int light) {
        float head = MathHelper.clamp(progress * 1.32F, 0.0F, 1.0F);
        float tail = Math.max(0.0F, head - 0.62F);
        float forwardEdge = Math.min(1.0F, head + 0.10F);
        float visibleLength = Math.max(0.05F, forwardEdge - tail);

        for (int segment = 0; segment < ARC_SEGMENTS; segment++) {
            float start = segment / (float) ARC_SEGMENTS;
            float end = (segment + 1) / (float) ARC_SEGMENTS;
            if (end < tail || start > forwardEdge) {
                continue;
            }

            float localProgress = MathHelper.clamp(
                    ((start + end) * 0.5F - tail) / visibleLength,
                    0.0F,
                    1.0F
            );
            float trailFade = MathHelper.clamp(localProgress * 2.2F, 0.08F, 1.0F);
            float headFade = MathHelper.clamp((1.0F - localProgress) * 6.0F, 0.25F, 1.0F);
            int segmentAlpha = Math.max(1, Math.round(alpha * trailFade * headFade));
            drawCrescentSegment(vertices, matrix, start, end, radiusX, radiusY, thickness,
                    red, green, blue, segmentAlpha, light);
        }
    }

private RenderPose resolveRenderPose(WraithmawCutlassEntity entity, float tickDelta) {
        Vec3d entityPos = new Vec3d(
                MathHelper.lerp(tickDelta, entity.prevX, entity.getX()),
                MathHelper.lerp(tickDelta, entity.prevY, entity.getY()),
                MathHelper.lerp(tickDelta, entity.prevZ, entity.getZ()));
        int cutlassState = entity.getState();
        Vec3d targetPosition = entityPos;
        Vec3d targetDirection = normalizedDirection(entity.getVelocity());
        if (cutlassState == WraithmawCutlassEntity.STATE_ORBITING) {
            Entity ownerEntity = entity.getWorld().getEntityById(entity.getOwnerId());
            if (!(ownerEntity instanceof LivingEntity owner)
                    || !owner.getMainHandStack().isOf(ItemsRegistry.WRAITHMAW.get())
                    && !owner.getOffHandStack().isOf(ItemsRegistry.WRAITHMAW.get())) {
                RENDER_STATES.remove(entity.getId());
                return null;
            }
            targetPosition = orbitPosition(entity, owner, tickDelta);
            double ownerYaw = Math.toRadians(MathHelper.lerpAngleDegrees(
                    tickDelta, owner.prevYaw, owner.getYaw()));
            targetDirection = new Vec3d(-Math.sin(ownerYaw), 0.0, Math.cos(ownerYaw));
        }

        float ageTicks = entity.age + tickDelta;
        long worldTick = entity.getWorld().getTime();
        RenderState renderState = RENDER_STATES.get(entity.getId());
        float deltaTicks = renderState == null ? 0.0F : ageTicks - renderState.lastAgeTicks;
        boolean reset = renderState == null
                || renderState.world != entity.getWorld()
                || !entity.getUuid().equals(renderState.entityUuid)
                || deltaTicks < 0.0F || deltaTicks > 5.0F;
        if (!reset && renderState.state == WraithmawCutlassEntity.STATE_ORBITING
                && cutlassState == WraithmawCutlassEntity.STATE_LAUNCHED) {
            targetPosition = entity.getPos();
        }
        if (reset) {
            renderState = new RenderState(entity.getWorld(), entity.getUuid(), targetPosition,
                    targetDirection, ageTicks, worldTick, cutlassState);
            RENDER_STATES.put(entity.getId(), renderState);
        } else {
            if (cutlassState == WraithmawCutlassEntity.STATE_ORBITING) {
                renderState.position = targetPosition;
            } else if (deltaTicks > 0.0F) {
                renderState.position = renderState.position.lerp(targetPosition,
                        response(POSITION_RESPONSE, deltaTicks));
            }
            if (cutlassState == WraithmawCutlassEntity.STATE_ORBITING) {
                renderState.direction = targetDirection;
            } else if ((cutlassState == WraithmawCutlassEntity.STATE_FALLING
                    || cutlassState == WraithmawCutlassEntity.STATE_LAUNCHED)
                    && targetDirection != null) {
                if (renderState.direction == null) {
                    renderState.direction = targetDirection;
                } else if (deltaTicks > 0.0F) {
                    renderState.direction = interpolateDirection(
                            renderState.direction, targetDirection,
                            response(DIRECTION_RESPONSE, deltaTicks));
                }
            }
            renderState.lastAgeTicks = ageTicks;
            renderState.lastWorldTick = worldTick;
            renderState.state = cutlassState;
        }
        if (entity.age % 80 == 0) {
            long cutoff = worldTick - 100L;
            RENDER_STATES.entrySet().removeIf(entry ->
                    entry.getKey() != entity.getId()
                            && (entry.getValue().world != entity.getWorld()
                            || entry.getValue().lastWorldTick < cutoff));
        }
        return new RenderPose(renderState.position.subtract(entityPos), renderState.direction);
    }

private static OrbitRenderPose resolveOrbitPose(ThrownSpearEntity entity, ItemStack stack,
                                                     float tickDelta) {
        if (!stack.isOf(ItemsRegistry.WICKPIERCER.get()) || !entity.hasOrbitPresentation()) {
            return null;
        }
        Entity targetEntity = entity.getWorld().getEntityById(entity.getOrbitTargetId());
        if (!(targetEntity instanceof LivingEntity target) || !target.isAlive() || target.isRemoved()) {
            return null;
        }
        int elapsedTicks = (int) entity.getWorld().getTime() - entity.getOrbitStartTick();
        double elapsed = elapsedTicks + tickDelta;
        int duration = entity.getOrbitDurationTicks();
        if (elapsed < 0.0 || elapsed > duration + 1.0) {
            return null;
        }
        double pathElapsed = Math.min(elapsed, duration);
        Vec3d targetCenter = new Vec3d(
                MathHelper.lerp(tickDelta, target.prevX, target.getX()),
                MathHelper.lerp(tickDelta, target.prevY, target.getY()) + target.getHeight() * 0.55,
                MathHelper.lerp(tickDelta, target.prevZ, target.getZ()));
        Vec3d entityPosition = new Vec3d(
                MathHelper.lerp(tickDelta, entity.prevX, entity.getX()),
                MathHelper.lerp(tickDelta, entity.prevY, entity.getY()),
                MathHelper.lerp(tickDelta, entity.prevZ, entity.getZ()));
        Vec3d currentOffset = WickpiercerThrowMath.orbitOffset(
                pathElapsed, entity.getOrbitIntervalTicks(), entity.getOrbitPhase(),
                WickpiercerThrowMath.DEFAULT_ORBIT_RADIUS);
        Vec3d desiredPosition = targetCenter.add(currentOffset);

        double sampleDistance = 0.08;
        double before = Math.max(0.0, pathElapsed - sampleDistance);
        double after = Math.min(duration, pathElapsed + sampleDistance);
        Vec3d beforeOffset = WickpiercerThrowMath.orbitOffset(
                before, entity.getOrbitIntervalTicks(), entity.getOrbitPhase(),
                WickpiercerThrowMath.DEFAULT_ORBIT_RADIUS);
        Vec3d afterOffset = WickpiercerThrowMath.orbitOffset(
                after, entity.getOrbitIntervalTicks(), entity.getOrbitPhase(),
                WickpiercerThrowMath.DEFAULT_ORBIT_RADIUS);
        double cycleAge = pathElapsed % entity.getOrbitIntervalTicks();
        double edgeWindow = sampleDistance;
        Vec3d direction;
        if (pathElapsed >= duration || cycleAge > entity.getOrbitIntervalTicks() - edgeWindow
                || pathElapsed > 0.0 && cycleAge < 1.0E-6) {
            direction = currentOffset.subtract(beforeOffset);
        } else if (cycleAge < edgeWindow) {
            direction = afterOffset.subtract(currentOffset);
        } else {
            direction = afterOffset.subtract(beforeOffset);
        }
        if (direction.lengthSquared() < 1.0E-6) {
            direction = entity.getVelocity();
        }
        if (direction.lengthSquared() < 1.0E-6) {
            direction = new Vec3d(0.0, 0.0, 1.0);
        }
        return new OrbitRenderPose(desiredPosition.subtract(entityPosition), direction.normalize());
    }

private void renderFootprint(World world, UUID id,
                                 double centerX, double centerY, double centerZ,
                                 SplatterShape shape, long shapeKey, float scanExtent,
                                 float fluidRadius, float verticalRange,
                                 Palette palette, float opacity,
                                 MatrixStack.Entry matrices,
                                 VertexConsumerProvider vertexConsumers) {
        opacity = MathHelper.clamp(opacity, 0.0F, 1.0F);
        if (opacity <= 0.01F || shape.parts.isEmpty()) {
            clear(id);
            return;
        }
        TerrainCache cache = getCache(
                world, id, centerX, centerY, centerZ, scanExtent, verticalRange, palette);
        if (cache.faces.isEmpty() && cache.fluidSurfaces.isEmpty()) {
            return;
        }

        SpriteSet sprites = palette.useBlockModelTextures
                ? SpriteSet.EMPTY
                : SpriteSet.load(palette);
        double minY = centerY - verticalRange;
        double maxY = centerY + verticalRange;
        PreparedGeometry preparedGeometry = prepareGeometry(
                cache, centerX, centerY, centerZ, shape, shapeKey, minY, maxY);
        List<PreparedFace> preparedFaces = preparedGeometry.faces;

        boolean translucent = opacity < 0.999F
                || shape.parts.stream().anyMatch(part -> part.opacity < 0.999F);
        VertexConsumer texturedVertices = vertexConsumers.getBuffer(
                translucent
                        ? RenderLayer.getEntityTranslucent(SpriteAtlasTexture.BLOCK_ATLAS_TEXTURE)
                        : RenderLayer.getCutout());
        for (PreparedFace prepared : preparedFaces) {
            float faceOpacity = opacity * prepared.part().opacity;
            if (palette == BLOOD_STAIN && faceOpacity >= 0.999F
                    && prepared.fullyCovered()
                    && !BLOOD_FACES_THIS_FRAME.add(prepared.face().key())) {
                continue;
            }
            if (prepared instanceof PreparedHorizontalFace horizontal) {
                drawHorizontalTextureFace(
                        centerX, centerY, centerZ, matrices, texturedVertices,
                        sprites, palette, faceOpacity, horizontal);
            } else if (prepared instanceof PreparedVerticalFace vertical) {
                drawVerticalTextureFace(
                        centerX, centerY, centerZ, matrices, texturedVertices,
                        sprites, palette, faceOpacity, vertical);
            }
        }
        if (sprites.fluidStill != null && sprites.fluidFlow != null) {
            for (SplatterPart part : shape.parts) {
                for (FluidSurface surface : cache.fluidSurfaces) {
                    drawFluidSurface(
                            centerX, centerY, centerZ,
                            matrices, texturedVertices, sprites,
                            surface, fluidRadius, part.points, minY, maxY
                    );
                }
            }
        }

        if (palette.washAlpha > 0) {
            VertexConsumer washVertices = vertexConsumers.getBuffer(
                    RenderLayer.getEntityTranslucent(WHITE_TEXTURE));
            for (PreparedFace prepared : preparedFaces) {
                float faceOpacity = opacity * prepared.part().opacity;
                if (prepared instanceof PreparedHorizontalFace horizontal) {
                    drawHorizontalWashFace(centerY, matrices, washVertices, palette, faceOpacity, horizontal);
                } else if (prepared instanceof PreparedVerticalFace vertical) {
                    drawVerticalWashFace(
                            centerX, centerY, centerZ, matrices, washVertices,
                            palette, faceOpacity, vertical);
                }
            }
        }
    }

private static FaceTextureMapping from(
                BakedQuad quad, Direction direction, Box bounds) {
            int[] data = quad.getVertexData();
            if (data.length < 24 || data.length % 4 != 0) {
                return null;
            }
            int stride = data.length / 4;
            if (stride < 6) {
                return null;
            }

            FaceBounds required = FaceBounds.of(direction, bounds);
            ModelVertex[] vertices = new ModelVertex[4];
            double actualMinFirst = Double.POSITIVE_INFINITY;
            double actualMaxFirst = Double.NEGATIVE_INFINITY;
            double actualMinSecond = Double.POSITIVE_INFINITY;
            double actualMaxSecond = Double.NEGATIVE_INFINITY;
            Sprite sprite = quad.getSprite();
            for (int i = 0; i < vertices.length; i++) {
                int offset = i * stride;
                double x = Float.intBitsToFloat(data[offset]);
                double y = Float.intBitsToFloat(data[offset + 1]);
                double z = Float.intBitsToFloat(data[offset + 2]);
                FaceCoordinates coordinates = FaceCoordinates.of(direction, x, y, z);
                double u = sprite.getFrameFromU(Float.intBitsToFloat(data[offset + 4]));
                double v = sprite.getFrameFromV(Float.intBitsToFloat(data[offset + 5]));
                vertices[i] = new ModelVertex(coordinates.first, coordinates.second, u, v);
                actualMinFirst = Math.min(actualMinFirst, coordinates.first);
                actualMaxFirst = Math.max(actualMaxFirst, coordinates.first);
                actualMinSecond = Math.min(actualMinSecond, coordinates.second);
                actualMaxSecond = Math.max(actualMaxSecond, coordinates.second);
            }
            if (actualMinFirst > required.minFirst + COVERAGE_EPSILON
                    || actualMaxFirst < required.maxFirst - COVERAGE_EPSILON
                    || actualMinSecond > required.minSecond + COVERAGE_EPSILON
                    || actualMaxSecond < required.maxSecond - COVERAGE_EPSILON) {
                return null;
            }

            ModelVertex origin = vertices[0];
            for (int first = 1; first < vertices.length; first++) {
                double firstDeltaA = vertices[first].first - origin.first;
                double firstDeltaB = vertices[first].second - origin.second;
                for (int second = first + 1; second < vertices.length; second++) {
                    double secondDeltaA = vertices[second].first - origin.first;
                    double secondDeltaB = vertices[second].second - origin.second;
                    double determinant = firstDeltaA * secondDeltaB
                            - secondDeltaA * firstDeltaB;
                    if (Math.abs(determinant) <= 1.0E-9) {
                        continue;
                    }
                    double uFirst = ((vertices[first].u - origin.u) * secondDeltaB
                            - (vertices[second].u - origin.u) * firstDeltaB) / determinant;
                    double uSecond = (firstDeltaA * (vertices[second].u - origin.u)
                            - secondDeltaA * (vertices[first].u - origin.u)) / determinant;
                    double vFirst = ((vertices[first].v - origin.v) * secondDeltaB
                            - (vertices[second].v - origin.v) * firstDeltaB) / determinant;
                    double vSecond = (firstDeltaA * (vertices[second].v - origin.v)
                            - secondDeltaA * (vertices[first].v - origin.v)) / determinant;
                    return new FaceTextureMapping(
                            origin.u - uFirst * origin.first - uSecond * origin.second,
                            uFirst, uSecond,
                            origin.v - vFirst * origin.first - vSecond * origin.second,
                            vFirst, vSecond,
                            required.minFirst, required.maxFirst,
                            required.minSecond, required.maxSecond);
                }
            }
            return null;
        }
